def _items(_value):
    if _value is None:
        return []
    if isinstance(_value, (list, tuple)):
        return [item for item in _value if item is not None]
    return [_value]


def _validate(_model, _label):
    if not isinstance(_model, dict):
        raise RuntimeError(_label + '必须是 JSON 对象（dict）')
    _scipy_name = _model.get('scipy_name') or _model.get('scipy分布名')
    if not _scipy_name or not hasattr(stats, str(_scipy_name)):
        raise RuntimeError(_label + '缺少有效的 scipy_name')
    _args = _model.get('args', _model.get('位置参数', [])) or []
    _kwargs = _model.get('kwargs', _model.get('命名参数', {})) or {}
    if not isinstance(_args, (list, tuple)) or not isinstance(_kwargs, dict):
        raise RuntimeError(_label + '的 args 必须是数组、kwargs 必须是对象')
    try:
        getattr(stats, str(_scipy_name))(*list(_args), **dict(_kwargs))
    except Exception as _err:
        raise RuntimeError(_label + '参数无效：' + str(_err))
    _result = copy.deepcopy(_model)
    _result['scipy_name'] = str(_scipy_name)
    _result['args'] = list(_args)
    _result['kwargs'] = dict(_kwargs)
    _result.setdefault('name', str(_scipy_name))
    _result.setdefault('type', 'discrete' if hasattr(getattr(stats, str(_scipy_name)), 'pmf') else 'continuous')
    _result.setdefault('estimated_param_count', 0)
    return _result


